def sequence(n, memo=None):
    if memo is None:
        memo = {1: 1, 2: 1, 3: 2, 4: 1, 5: 2, 6: 1, 7: 1, 8: 2, 9: 1, 10: 6}

    if n in memo:
        return memo[n]

    memo[n] = sequence(n - sequence(n - 1), memo) + sequence(n - sequence(n - 2), memo)
    return memo[n]

